function names = zernikeModeNames(maxOrder)
%ZERNIKEMODENAMES Supported named Zernike aberration modes.
%
%   names = zernikeModeNames()
%   names = zernikeModeNames(maxOrder)
%
%   The basis follows the existing repository convention: coefficients are
%   RMS waves at sim.lamRef, and sine/cosine pairs are named with legacy x/y
%   suffixes. For astigmatism, astig_x is the 0/90-degree cos(2phi) term and
%   astig_y is the 45/135-degree sin(2phi) term. Piston is intentionally
%   excluded. Defocus is listed so callers that need it can request it,
%   although focal-position fitting usually absorbs it. The basis now spans
%   radial orders 1-7; maxOrder 5 gives the 20-mode set used for the
%   23-channel array and maxOrder 7 the 35-mode set used for the 93-channel
%   array.

    if nargin < 1 || isempty(maxOrder)
        maxOrder = 6;
    end

    all = { ...
        'tilt_x',              1; ...
        'tilt_y',              1; ...
        'defocus',             2; ...
        'astig_x',             2; ...
        'astig_y',             2; ...
        'coma_x',              3; ...
        'coma_y',              3; ...
        'trefoil_x',           3; ...
        'trefoil_y',           3; ...
        'spherical',           4; ...
        'secondary_astig_x',   4; ...
        'secondary_astig_y',   4; ...
        'quadrafoil_x',        4; ...
        'quadrafoil_y',        4; ...
        'secondary_coma_x',    5; ...
        'secondary_coma_y',    5; ...
        'secondary_trefoil_x', 5; ...
        'secondary_trefoil_y', 5; ...
        'pentafoil_x',         5; ...
        'pentafoil_y',         5; ...
        'secondary_spherical', 6; ...
        'tertiary_astig_x',    6; ...
        'tertiary_astig_y',    6; ...
        'secondary_quadrafoil_x', 6; ...
        'secondary_quadrafoil_y', 6; ...
        'hexafoil_x',          6; ...
        'hexafoil_y',          6; ...
        'tertiary_coma_x',        7; ...
        'tertiary_coma_y',        7; ...
        'tertiary_trefoil_x',     7; ...
        'tertiary_trefoil_y',     7; ...
        'secondary_pentafoil_x',  7; ...
        'secondary_pentafoil_y',  7; ...
        'heptafoil_x',            7; ...
        'heptafoil_y',            7};

    keep = cell2mat(all(:,2)) <= maxOrder;
    names = all(keep,1).';
end
